CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE agents(id TEXT PRIMARY KEY,name TEXT NOT NULL,mission TEXT NOT NULL,color TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE tasks(id TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES agents(id),origin TEXT NOT NULL,kind TEXT NOT NULL,priority INTEGER NOT NULL,description TEXT NOT NULL,input TEXT NOT NULL,dependencies TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,planned_at TEXT NOT NULL,last_run TEXT,attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL,files TEXT NOT NULL DEFAULT '[]',result TEXT,cost_estimate TEXT NOT NULL,permissions TEXT NOT NULL,correlation_id TEXT NOT NULL,dedupe_key TEXT UNIQUE,requires_ai INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',finished_at TEXT);
CREATE UNIQUE INDEX one_executor ON tasks((1)) WHERE state IN ('RUNNING','CHECKPOINTING');
CREATE TABLE task_history(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id TEXT NOT NULL REFERENCES tasks(id),from_state TEXT,to_state TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE events(id TEXT PRIMARY KEY,type TEXT NOT NULL,payload TEXT NOT NULL,dedupe_key TEXT NOT NULL UNIQUE,task_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE records(id TEXT PRIMARY KEY,entity TEXT NOT NULL,project_id TEXT,data TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX records_entity ON records(entity,created_at);
CREATE VIEW leads AS SELECT * FROM records WHERE entity='leads';
CREATE VIEW clients AS SELECT * FROM records WHERE entity='clients';
CREATE VIEW deals AS SELECT * FROM records WHERE entity='deals';
CREATE VIEW payments AS SELECT * FROM records WHERE entity='payments';
CREATE VIEW projects AS SELECT * FROM records WHERE entity='projects';
CREATE VIEW requirements AS SELECT * FROM records WHERE entity='requirements';
CREATE VIEW content_items AS SELECT * FROM records WHERE entity='content_items';
CREATE VIEW publications AS SELECT * FROM records WHERE entity='publications';
CREATE TABLE approvals(id TEXT PRIMARY KEY,task_id TEXT,action TEXT NOT NULL,scope TEXT NOT NULL,justification TEXT NOT NULL,risk TEXT NOT NULL,consequences TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,decided_at TEXT);
CREATE TABLE instructions(id TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES agents(id),version INTEGER NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(agent,version));
CREATE TABLE training_proposals(id TEXT PRIMARY KEY,agent TEXT NOT NULL,problem TEXT NOT NULL,source TEXT NOT NULL,technique TEXT NOT NULL,previous_version INTEGER NOT NULL,new_version INTEGER NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE training_evaluations(id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL REFERENCES training_proposals(id),tests TEXT NOT NULL,result TEXT NOT NULL,passed INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE usage_snapshots(id TEXT PRIMARY KEY,source TEXT NOT NULL,windows TEXT NOT NULL,observed_at TEXT NOT NULL,remaining_jobs INTEGER NOT NULL DEFAULT 0,detail TEXT NOT NULL);
CREATE TABLE reports(id TEXT PRIMARY KEY,task_id TEXT,title TEXT NOT NULL,path TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id TEXT,agent TEXT,action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE integrations(id TEXT PRIMARY KEY,state TEXT NOT NULL,detail TEXT NOT NULL,capabilities TEXT NOT NULL,checked_at TEXT NOT NULL);
CREATE TABLE schedule_runs(key TEXT PRIMARY KEY,event TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE cache(key TEXT PRIMARY KEY,result TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE notifications(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL,seen INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
